package app.relaydrop;

import org.json.JSONObject;
import javax.net.ssl.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.cert.*;
import java.util.*;
import java.util.concurrent.*;

/** Bounded byte-only forwarding. Only endpoint devices terminate the inner TLS session. */
final class RemoteTunnel implements Closeable {
  private static final int MAX_STREAMS=8;
  private final Set<Socket> sockets=Collections.synchronizedSet(new HashSet<Socket>());
  private final Semaphore permits=new Semaphore(MAX_STREAMS);
  private final ExecutorService workers=Executors.newFixedThreadPool(18,r->{Thread t=new Thread(r,"relay-remote-io");t.setDaemon(true);return t;});
  private final ScheduledExecutorService timers=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"relay-remote-timer");t.setDaemon(true);return t;});
  private volatile boolean closed;
  volatile String status="未连接";
  private ServerSocket listener;
  private Thread control;
  private Socket controlSocket;
  private final JSONObject config;
  private final boolean host;
  private final String clientSession=RemoteConnections.token();
  private final Map<Socket,Integer> registered=new ConcurrentHashMap<>();
  private int localPort;
  RemoteTunnel(JSONObject config,boolean host){this.config=config;this.host=host;}
  static JSONObject readLine(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();for(int n;(n=in.read())!=-1;){if(n==10){if(out.size()==0)throw new IOException("Empty remote frame");return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}if(n==13||out.size()>=8192)throw new IOException("Invalid remote frame");out.write(n);}throw new EOFException("远程连接已断开。");}
  static void line(OutputStream out,JSONObject value)throws Exception{byte[] bytes=(value.toString()+"\n").getBytes(StandardCharsets.UTF_8);if(bytes.length>8192)throw new IOException("Remote frame too large");synchronized(out){out.write(bytes);out.flush();}}
  static final class Rejected extends IOException{final String code;Rejected(String code){super("中继拒绝连接，请核对配置，或确认文件池设备在线。");this.code=code!=null&&code.matches("[A-Z_]{1,40}")?code:"INVALID_RESPONSE";}}
  static void accepted(JSONObject value)throws IOException{if(!Boolean.TRUE.equals(value.opt("ok")))throw new Rejected(value.optString("code"));}
  private static boolean permanent(Exception error){if(error instanceof Rejected){String code=((Rejected)error).code;return code.matches("UNAUTHORIZED|ROOM_OWNER_MISMATCH|HOST_ALREADY_ONLINE|INVALID_CONFIG|INVALID_HEADER|INVALID_RESPONSE");}for(Throwable t=error;t!=null;t=t.getCause())if(t instanceof CertificateException||t instanceof SSLPeerUnverifiedException)return true;return false;}
  private Socket broker()throws Exception{
    URI endpoint=RemoteConnections.relay(config.getString("relay"));String pin=config.isNull("relayFingerprint")?null:config.optString("relayFingerprint",null);SSLSocketFactory factory;
    if(pin==null){KeyStore system=KeyStore.getInstance("AndroidCAStore");system.load(null);TrustManagerFactory tm=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());tm.init(system);SSLContext ctx=SSLContext.getInstance("TLS");ctx.init(null,tm.getTrustManagers(),new SecureRandom());factory=ctx.getSocketFactory();}else{if(!pin.matches(RemoteConnections.PIN))throw new IOException("Invalid relay pin");final String expected=pin;SSLContext ctx=SSLContext.getInstance("TLS");ctx.init(null,new TrustManager[]{new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] c,String a)throws CertificateException{throw new CertificateException();}public void checkServerTrusted(X509Certificate[] c,String a)throws CertificateException{try{if(c==null||c.length==0)throw new CertificateException();c[0].checkValidity();if(!expected.equals(TlsIdentity.fingerprint(c[0])))throw new CertificateException("中继证书不匹配。");}catch(CertificateException e){throw e;}catch(Exception e){throw new CertificateException(e);}}}},new SecureRandom());factory=ctx.getSocketFactory();}
    Socket raw=new Socket();track(raw);SSLSocket secured=null;try{raw.connect(new InetSocketAddress(endpoint.getHost().replace("[", "").replace("]", ""),endpoint.getPort()),10000);secured=(SSLSocket)factory.createSocket(raw,endpoint.getHost(),endpoint.getPort(),true);track(secured);sockets.remove(raw);secured.setEnabledProtocols(TlsIdentity.protocols());if(pin==null){SSLParameters p=secured.getSSLParameters();p.setEndpointIdentificationAlgorithm("HTTPS");secured.setSSLParameters(p);}secured.setSoTimeout(15000);secured.startHandshake();return secured;}catch(Exception e){closeSocket(secured);closeSocket(raw);throw e;}
  }
  private void track(Socket s)throws IOException{synchronized(sockets){if(closed){s.close();throw new IOException("远程连接已停止。");}sockets.add(s);}}
  private void closeSocket(Socket s){if(s==null)return;Integer port=registered.remove(s);RelayHttpServer server=RelayService.server;if(port!=null&&server!=null)server.unregisterRemotePeer(port);sockets.remove(s);try{s.close();}catch(Exception ignored){}}
  int startClient(int preferredPort)throws Exception{if(host)throw new IllegalStateException();listener=new ServerSocket();listener.setReuseAddress(true);listener.bind(new InetSocketAddress("127.0.0.1",preferredPort),8);localPort=listener.getLocalPort();status="远程入口就绪（文件池需在线）";control=new Thread(()->{while(!closed)try{Socket local=listener.accept();if(!permits.tryAcquire()){local.close();continue;}track(local);workers.execute(()->{Socket remote=null;try{remote=broker();line(remote.getOutputStream(),new JSONObject().put("v",1).put("op","join").put("session",clientSession).put("room",config.getString("room")).put("joinKey",config.getString("joinKey")));accepted(readLine(remote.getInputStream()));status="远程传输中";bridge(local,remote);}catch(Exception e){status="远程暂不可用，请确认文件池和中继在线";closeSocket(local);closeSocket(remote);permits.release();}});}catch(Exception e){if(!closed)status="远程入口已中断";break;}},"relay-remote-accept");control.setDaemon(true);control.start();return localPort;}
  void startHost(int localTlsPort)throws Exception{if(!host)throw new IllegalStateException();localPort=localTlsPort;control=new Thread(()->{long delay=1000;while(!closed){Socket s=null;ScheduledFuture<?> heartbeat=null;try{status="正在连接中继…";s=broker();controlSocket=s;line(s.getOutputStream(),new JSONObject().put("v",1).put("op","host").put("room",config.getString("room")).put("serviceKey",config.getString("serviceKey")).put("hostKey",config.getString("hostKey")).put("joinKey",config.getString("joinKey")));accepted(readLine(s.getInputStream()));status="远程共享在线";delay=1000;s.setSoTimeout(65000);final Socket channel=s;heartbeat=timers.scheduleAtFixedRate(()->{try{line(channel.getOutputStream(),new JSONObject().put("op","ping"));}catch(Exception e){closeSocket(channel);}},20,20,TimeUnit.SECONDS);while(!closed){JSONObject event=readLine(s.getInputStream());String op=event.optString("op");if("open".equals(op)){if(!event.getString("id").matches(RemoteConnections.UUID)||!event.getString("ticket").matches(RemoteConnections.SECRET))throw new IOException("Invalid remote request");if(permits.tryAcquire())workers.execute(()->attach(event));}else if(!"pong".equals(op))throw new IOException("Invalid control frame");}}catch(Exception e){if(!closed){if(permanent(e)){status="身份或配置校验失败，请核对中继证书和服务密钥后重新开启";closed=true;workers.shutdownNow();timers.shutdownNow();}else status="连接中断，等待自动重连";}}finally{if(heartbeat!=null)heartbeat.cancel(false);closeSocket(s);controlSocket=null;closeDataSockets();}if(!closed)try{Thread.sleep(delay);delay=Math.min(30000,delay*2);}catch(InterruptedException ignored){}}},"relay-remote-host");control.setDaemon(true);control.start();}
  private void attach(JSONObject event){Socket local=null,remote=null;try{local=new Socket();track(local);local.connect(new InetSocketAddress("127.0.0.1",localPort),5000);String peer=event.optString("peerId");if(!peer.isEmpty()&&!peer.matches("[a-f0-9]{64}"))throw new IOException("Invalid trusted peer identity");RelayHttpServer server=RelayService.server;if(server!=null&&!peer.isEmpty()){server.registerRemotePeer(local.getLocalPort(),peer);registered.put(local,local.getLocalPort());}remote=broker();line(remote.getOutputStream(),new JSONObject().put("v",1).put("op","attach").put("room",config.getString("room")).put("id",event.getString("id")).put("ticket",event.getString("ticket")));accepted(readLine(remote.getInputStream()));bridge(local,remote);}catch(Exception e){closeSocket(local);closeSocket(remote);permits.release();}}
  private void bridge(Socket a,Socket b)throws Exception{a.setSoTimeout(10000);b.setSoTimeout(10000);final java.util.concurrent.atomic.AtomicBoolean done=new java.util.concurrent.atomic.AtomicBoolean();final java.util.concurrent.atomic.AtomicInteger directions=new java.util.concurrent.atomic.AtomicInteger(2);final java.util.concurrent.atomic.AtomicLong activity=new java.util.concurrent.atomic.AtomicLong(System.nanoTime());final ScheduledFuture<?>[] timeout={null};Runnable finish=()->{if(done.compareAndSet(false,true)){if(timeout[0]!=null)timeout[0].cancel(false);closeSocket(a);closeSocket(b);permits.release();}};Runnable eof=()->{if(directions.decrementAndGet()==0)finish.run();};timeout[0]=timers.scheduleAtFixedRate(()->{if(System.nanoTime()-activity.get()>TimeUnit.SECONDS.toNanos(120))finish.run();},10,10,TimeUnit.SECONDS);workers.execute(()->copy(b,a,activity,finish,eof));copy(a,b,activity,finish,eof);}
  private void copy(Socket from,Socket to,java.util.concurrent.atomic.AtomicLong activity,Runnable fail,Runnable eof){try{InputStream in=from.getInputStream();OutputStream out=to.getOutputStream();byte[] bytes=new byte[32768];while(!closed){int n;try{n=in.read(bytes);}catch(SocketTimeoutException timeout){if(System.nanoTime()-activity.get()>TimeUnit.SECONDS.toNanos(120))throw timeout;continue;}if(n==-1){try{to.shutdownOutput();}catch(Exception ignored){}eof.run();return;}activity.set(System.nanoTime());out.write(bytes,0,n);out.flush();activity.set(System.nanoTime());}fail.run();}catch(Exception ignored){fail.run();}}
  private void closeDataSockets(){synchronized(sockets){for(Socket s:new ArrayList<>(sockets))if(s!=controlSocket)closeSocket(s);}}
  @Override public void close(){closed=true;status="已停止";try{if(listener!=null)listener.close();}catch(Exception ignored){}synchronized(sockets){for(Socket s:new ArrayList<>(sockets))closeSocket(s);}if(control!=null)control.interrupt();workers.shutdownNow();timers.shutdownNow();}
  int port(){return localPort;}
}
